var article = "";

// Introduction
// Deeper Research Format
if($('Settings').first().json['Have Deeper Research'].toLowerCase() === "yes"){
  article += "## " + $('Blog Planner').first().json.output.introduction_title + "\n" 
}

article += $('Blog Planner').first().json.output.introduction;
article += "\n";

var index = 0;
for (const item of $input.all()) {
  // Add the chapter title as a Markdown level 2 header
  article += "## " + $('Merge Chapters').all()[index].json.chapter_title + "\n";

    // Insert the chapter image if it exists (using Markdown image syntax)
  if (item.json.source_url) {
    article += `![${item.json.title.rendered}](${item.json.source_url})\n`;
  }

  if($('Settings').first().json['Have Deeper Research'].toLowerCase() !== "yes"){
    // Add the chapter content
    article += $('Merge Chapters').all()[index].json.chapter_content;
    article += "\n";
  }else
  {
    var i = 0;
  // Add the chapter content
    for (const content of $('Merge Chapters').all()[index].json.subchapters){
        article += "### " + (i + 1) + ". " + content.subchapter_title;
        article += "\n";
        article += content.subchapter_content;
        article += "\n";
        i++;
    }
  }
  index++;
}

// Conclusion
article += "## " + $('Blog Planner').first().json.output.conclusion_title + "\n";
article += $('Blog Planner').first().json.output.conclusion;
article += "\n";

// Call-to-Action (CTA)
article += $('Blog Planner').first().json.output.cta + "\n";

// About Company
article += "## " + $('Blog Planner').first().json.output.about_us_title + "\n";
article += $('Blog Planner').first().json.output.about_company

return [
  {
    "article": article
  }
];

